      SUBROUTINE THORCC     CALCULATES THIRD-ORDER MATRIX ELEMENTSCC ----------------------------------------------------------------------      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'DATA0A.CIN'      INCLUDE 'DATA2A.CIN'      INCLUDE 'ELM0A.CIN'      INCLUDE 'ELM0B.CIN'      INCLUDE 'ELM0C.CIN'      INCLUDE 'ELM4A.CIN'      INCLUDE 'ELM4B.CIN'      INCLUDE 'ELM5A.CIN'      INCLUDE 'ELM5B.CIN'      INCLUDE 'ELM14A.CIN'      INCLUDE 'ELM15A.CIN'      INCLUDE 'ELM15C.CIN'      INCLUDE 'U.CIN'C      INTEGER         IA, IDATA, IND, IND0, IND1, IX, K, M      EXTERNAL        IDATAC ----------------------------------------------------------------------C      IF (TYPE .EQ. 14 .AND. TYP1 .EQ. 14) GO TO 1400      DO 11 IA = 1, 280   11 UL(IA) = 0.0      GO TO (5000, 200, 300, 400, 500,5000,5000,5000,5000,5000,     1       5000,5000,5000,1400,5000,5000,5000,1800,1900,5000,     2       5000,5000,5000,5000,2500,5000,5000,5000,5000,5000,     3       5000,5000,5000,3400,3500,3500,5000,5000,5000,5000,     4       5000,3500,5000,5000,5000,5000,5000,5000), TYPECCC     2. -- POLE FACE ROTATIONC  200 CALL FRING3      GO TO 5000CC     3. -- DRIFT SPACEC  300 CONTINUE      GO TO 5000CC     4. -- BENDING MAGNETC  400 IF (H0 .EQ. 0) GO TO 5000      H = (1.0 + RMPS)*H0      GAB = GAM/(H0*UNITI(1))**3C      CALL THORC      CALL THORS      CALL THORD      CALL THORU      GO TO 5000CC     5. -- QUADRUPOLEC  500 JQUAD = 1      KQ2 = KX2      CALL FOCUS3      JQUAD = 3      KQ2 = KY2      CALL FOCUS3      GO TO 5000CC     14. -- ARBITRARY MATRIXC 1400 IF (I14S .NE. 0) GO TO 1420      I14T = IDATA(I+30)      IF (I14T .NE. 0) GO TO 1420      IX = I + 30      IND0 = 1      DO 1410 J = 1, 6      IND1 = IND0      DO 1408 K = J, 6      IND = IND1      DO 1406 M = K, 6      IX = IX + 1      U(J1,IND) = DATA(IX)*UBEAM(J1)/(UBEAM(J)*UBEAM(K)*UBEAM(M))      IND = IND + M*(M+1)/2 1406 CONTINUE      IND1 = IND1 + K*(K+3)/2 1408 CONTINUE      IND0 = IND0 + (J+1)*(J+2)/2 1410 CONTINUE 1420 IF (NUM + 1 .GT. NEL) GO TO 5000      IF (NEXT .EQ. 14) RETURN      GO TO 5000CC     18. -- SEXTUPOLEC 1800 CALL SEXT3      GO TO 5000CC     19. -- SOLENOIDC 1900 CONTINUE      GO TO 5000CC     25. -- OCTUPOLEC 2500 CALL OCTUPL      GO TO 5000CC     34. -- PLASMA LENSC 3400 CONTINUE      GO TO 5000CC     35. -- HKICK -- HORIZONTAL VERNIERC                     ORC     36. -- VKICK -- VERTICAL VERNIERC 3500 U(1,38) = 0.75*AL*L      U(1,45) = 0.25*AL*L      U(1,56) = 0.5*AL*L      U(2,38) = 1.5*AL      U(2,45) = 0.5*AL      U(2,56) = AL      U(3,43) = 0.5*AL*L      U(4,43) = AL      GO TO 5000CC     RETURNC 5000 RETURN      END